import json
from decimal import Decimal
from typing import Any, Dict, Optional

import pydantic


class Document(pydantic.BaseModel):
    id: str
    document: Dict[str, Any]
    key_field: Optional[str] = "id"


class DocumentQuery(pydantic.BaseModel):
    table_name: str
    key_field: str
    key_value: str


class DecimalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return str(obj)
        return json.JSONEncoder.default(self, obj)

import os
from decimal import Decimal

from boto3.dynamodb.conditions import Key

from database_client import get_dynamodb_resource


def query_documents(field_name, field_value, table_name=None, index_name=None):
    table_name = table_name or os.environ.get("DYNAMODB_TABLE_NAME")

    if not table_name:
        raise ValueError("DynamoDB table name not provided.")

    dynamodb = get_dynamodb_resource()
    table = dynamodb.Table(table_name)

    query_kwargs = {
        "KeyConditionExpression": Key(field_name).eq(field_value),
    }
    if index_name:
        query_kwargs["IndexName"] = index_name

    response = table.query(**query_kwargs)
    return response.get("Items", [])

import os

import boto3


def archive_document_snapshot(file_content, bucket_name, object_key):
    region_name = os.environ.get("AWS_REGION", "us-east-1")
    s3_client = boto3.client("s3", region_name=region_name)

    try:
        s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=file_content)
        return {
            "message": f"Successfully archived {object_key} to s3://{bucket_name}",
            "bucket": bucket_name,
            "object_key": object_key,
            "provider": "AWS S3",
        }
    except Exception as e:
        return {"error": str(e), "provider": "AWS S3"}
